package exercise
import("bufio";"net";"net/http")
type state struct{http.ResponseWriter;status,bytes int}
func(s *state)WriteHeader(code int){if s.status!=0{return};s.status=code;s.ResponseWriter.WriteHeader(code)}
func(s *state)Write(p []byte)(int,error){if s.status==0{s.WriteHeader(200)};n,e:=s.ResponseWriter.Write(p);s.bytes+=n;return n,e}
type flushOnly struct{*state}
func(s flushOnly)Flush(){if s.status==0{s.WriteHeader(200)};s.ResponseWriter.(http.Flusher).Flush()}
type hijackOnly struct{*state}
func(s hijackOnly)Hijack()(net.Conn,*bufio.ReadWriter,error){return s.ResponseWriter.(http.Hijacker).Hijack()}
type both struct{*state}
func(s both)Flush(){if s.status==0{s.WriteHeader(200)};s.ResponseWriter.(http.Flusher).Flush()}
func(s both)Hijack()(net.Conn,*bufio.ReadWriter,error){return s.ResponseWriter.(http.Hijacker).Hijack()}
func Wrap(next http.Handler,report func(int,int))http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){s:=&state{ResponseWriter:w};defer func(){report(s.status,s.bytes)}();_,f:=w.(http.Flusher);_,h:=w.(http.Hijacker);var out http.ResponseWriter=s;if f&&h{out=both{s}}else if f{out=flushOnly{s}}else if h{out=hijackOnly{s}};next.ServeHTTP(out,r)})}
```

原题知识说明：
交付ResponseWriter能力矩阵，分别列出普通响应、Flush、Hijack及目标版本ResponseController所需接口；简单包一层只实现Header、Write、WriteHeader可能隐藏底层能力。设计应明确通过受支持的Unwrap链或接口转发保留能力，同时不能声称HTTP/2也支持HTTP/1连接接管。记录首次最终状态码、累计实际写入字节和写失败，处理未显式WriteHeader的情况。验收覆盖SSE分段刷新、升级连接、零正文、客户端中断和多个中间件叠加，比较有无封装的协议行为。失败时撤回中间件版本并保留必要外围日志，不能为了恢复日志指标把流式接口改成全量缓冲；实现由开发提交后按矩阵验证。

