package exercise
import("bufio";"context";"errors";"fmt";"io";"net";"net/http";"net/http/httptest";"strings";"testing";"time")
type plain struct{header http.Header;status int;writes int;short bool}
func(p *plain)Header()http.Header{return p.header}
func(p *plain)WriteHeader(code int){p.status=code}
func(p *plain)Write(b []byte)(int,error){p.writes++;if p.short&&len(b)>0{return 1,io.ErrShortWrite};return len(b),nil}
type flusher struct{*plain}
func(f *flusher)Flush(){}
type hijacker struct{*plain}
func(h *hijacker)Hijack()(net.Conn,*bufio.ReadWriter,error){return nil,nil,errors.New("marker")}
type bothWriter struct{*plain}
func(b *bothWriter)Flush(){}
func(b *bothWriter)Hijack()(net.Conn,*bufio.ReadWriter,error){return nil,nil,errors.New("marker")}
func TestCapabilityMatrixAndStatus(t *testing.T){
 for _,row:=range []struct{writer http.ResponseWriter;f,h bool}{{&plain{header:http.Header{}},false,false},{&flusher{&plain{header:http.Header{}}},true,false},{&hijacker{&plain{header:http.Header{}}},false,true},{&bothWriter{&plain{header:http.Header{}}},true,true}}{
  count,status,bytes:=0,0,0;handler:=Wrap(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){_,f:=w.(http.Flusher);_,h:=w.(http.Hijacker);if f!=row.f||h!=row.h{t.Fatal("supported capability changed",f,h,row.f,row.h)};w.WriteHeader(201);w.WriteHeader(500);w.Write([]byte("abc"))}),func(s,n int){count++;status=s;bytes=n})
  handler.ServeHTTP(row.writer,httptest.NewRequest("GET","/",nil));if count!=1||status!=201||bytes!=3{t.Fatal("status or byte accounting",count,status,bytes)}
 }
 p:=&plain{header:http.Header{},short:true};status,n:=0,0;Wrap(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Write([]byte("abcd"))}),func(a,b int){status=a;n=b}).ServeHTTP(p,httptest.NewRequest("GET","/",nil));if status!=200||n!=1{t.Fatal("actual short write count",status,n)}
}
func TestStreamingAndHijackOnRealServer(t *testing.T){
 release:=make(chan struct{});reports:=make(chan string,2)
 server:=httptest.NewServer(Wrap(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
  if r.URL.Path=="/stream"{fmt.Fprint(w,"first\n");w.(http.Flusher).Flush();<-release;fmt.Fprint(w,"last\n");return}
  conn,rw,e:=w.(http.Hijacker).Hijack();if e!=nil{return};defer conn.Close();fmt.Fprint(rw,"HTTP/1.1 101 Switching Protocols\r\nConnection: upgrade\r\nUpgrade: test\r\n\r\nowned");rw.Flush()
 }),func(s,n int){reports<-fmt.Sprintf("%d:%d",s,n)}));defer server.Close()
 ctx,cancel:=context.WithTimeout(context.Background(),3*time.Second);defer cancel();req,_:=http.NewRequestWithContext(ctx,"GET",server.URL+"/stream",nil);resp,e:=http.DefaultClient.Do(req);if e!=nil{t.Fatal(e)};reader:=bufio.NewReader(resp.Body);line,e:=reader.ReadString('\n');if e!=nil||line!="first\n"{t.Fatal("first stream chunk not flushed",line,e)};close(release);rest,e:=io.ReadAll(reader);resp.Body.Close();if e!=nil||string(rest)!="last\n"{t.Fatal("remaining stream",string(rest),e)}
 addr:=strings.TrimPrefix(server.URL,"http://");conn,e:=net.DialTimeout("tcp",addr,time.Second);if e!=nil{t.Fatal(e)};conn.SetDeadline(time.Now().Add(2*time.Second));fmt.Fprint(conn,"GET /upgrade HTTP/1.1\r\nHost: example\r\nConnection: upgrade\r\nUpgrade: test\r\n\r\n");data,e:=io.ReadAll(conn);conn.Close();if e!=nil||!strings.Contains(string(data),"101 Switching Protocols")||!strings.HasSuffix(string(data),"owned"){t.Fatal("actual hijack failed",string(data),e)}
 got:=map[string]bool{<-reports:true,<-reports:true};if !got["200:11"]||!got["0:0"]{t.Fatal("stream or hijack accounting",got)}
 t.Log("NATIVE_GO_HTTP_REAL_FLUSH_BEFORE_HANDLER_RELEASE_AND_HTTP1_HIJACK_SUCCESS")
}
